    id: "douglas-hawkins", kind: "person", asOf, name: "Douglas S. Hawkins", role: "Group Chair, Children's Oncology Group; Professor of Pediatrics, Seattle Children's and University of Washington", institutionId: "childrens-oncology-group", institutions: ["childrens-oncology-group", "fred-hutch"],
